float tetrahedron(vec3 p, float r) {

    // basically cutting a cube at the diagonal and scaling/centering it.
    p.yz *= rot(PI/2.);

    p.z -= ISQR2*r;
    vec3 bp = p;
    p.z *=  0.5;
    p.z -= ISQR2*r;

    p.yz *= rot(atan(ISQR2)*PI*.5);
    p.xy *= rot(PI/4.);

    return smax(cube(p, r)-.15, bp.z, .15)*.5;
}


